/-- Full-support schedule weights used only to select an objective. -/
def FullSupportWeight (E : Setup) (q : Theta E → ℝ) : Prop :=
  (∀ θ, 0 < q θ) ∧ ∑ θ, q θ = 1

/-- Universal randomization conservativeness of an assignment rule. -/
def UniversallyConservative (E : Setup) (g : AssignmentRule E) : Prop :=
  ∀ θ, E.design.Var (fun z => score E z θ) ≤ expectedRule E g θ

/-- Inclusion-exclusion coefficient of a Boolean function. -/
def beta (E : Setup) (u : Theta E → ℝ) (S : Finset (Fin E.K)) : ℝ :=
  ∑ T ∈ S.powerset, (-1 : ℝ) ^ (S.card - T.card) * u (vertex E T)

/-- The expected block bound. -/
def blockBoundMean (B : ℕ) (j : Fin B) : ℝ :=
  (Arr.rowLaw B).E (fun w => Arr.G B j (w j))

/-- The block score's design mean. -/
def blockTau (B : ℕ) (j : Fin B) : ℝ :=
  (Arr.rowLaw B).E (fun w => Arr.X B j (w j))

/-- Weighted objective of a Boolean bound. -/
def boundObjective (E : Setup) (q : FullSupportObjective E) (b : Theta E → ℝ) : ℝ :=
  ∑ θ, q.1 θ * b θ

/-- Centered binary coordinate. -/
def centeredCoord {E : Setup} (θ : Theta E) (i : Fin E.K) : ℝ :=
  2 * ((θ i : ℕ) : ℝ) - 1

/-- Degree-restricted observable functions that dominate the true variance pointwise. -/
def conservativeCone (E : Setup) (r : WithTop ℕ) : Set (Theta E → ℝ) :=
  {b | b ∈ observableSpan E r ∧ ∀ θ, trueVarianceFn E θ ≤ b θ}

/-- Nonnegative schedule weights matching every observable Boolean moment of `q`. -/
def dualMarginSet (E : Setup) (q : FullSupportObjective E) : Set (Theta E → ℝ) :=
  {μ | (∀ θ, 0 ≤ μ θ) ∧
    ∀ S ∈ observableComplex E,
      ∑ θ, μ θ * monomial E S θ = ∑ θ, q.1 θ * monomial E S θ}

/-- Dual objective. -/
def dualObjective (E : Setup) (μ : Theta E → ℝ) : ℝ :=
  ∑ θ, μ θ * trueVarianceFn E θ

/-- Joint probability that every coordinate of `S` is observed. -/
def jointObsProb (E : Setup) (S : Finset (Fin E.K)) : ℝ :=
  E.design.E fun z => if S ⊆ E.O z then 1 else 0

/-- Read an observed bit, returning zero only outside the observation set. -/
def localBit (E : Setup) (z : E.Omega) (y : E.O z → Fin 2) (i : Fin E.K) : ℕ :=
  if h : i ∈ E.O z then (y ⟨i, h⟩ : ℕ) else 0

/-- For [a six-coordinate binary schedule](hyp:θ), [the rational μ-star weight](goal) is the specified uniform certificate weight. -/
-- @node: muStarRat
def muStarRat (θ : Fin 6 → Fin 2) : ℚ :=
  if witnessCodeNat θ ∈ ([0,7,11,14,19,20,28,31,32,39,43,44,48,53,56,59] : List ℕ)
  then 1 / 16 else 0

/-- A local observed binary coordinate, coerced to a real. -/
def observedReal (E : Setup) (z : E.Omega) (y : E.O z → Fin 2) (i : Fin E.K) : ℝ :=
  if h : i ∈ E.O z then ((y ⟨i, h⟩ : ℕ) : ℝ) else 0

/-- For [a block collection](hyp:B,comp), [score weights](hyp:a), and [a degree bound](hyp:r), [the product conservative cone](goal) contains observable rules that dominate the product variance at every schedule. -/
def productConservativeCone (B : ℕ) (comp : Fin B → Setup) (a : Fin B → ℝ)
    (r : WithTop ℕ) : Set (ProductTheta B comp → ℝ) :=
  {b | b ∈ productObservableSpan B comp r ∧ ∀ θ, productVarianceFn B comp a θ ≤ b θ}

/-- Joint supports observable under a product-assignment atom. -/
def productObservableComplex (B : ℕ) (comp : Fin B → Setup) :
    Set (Finset (ProductCoordinate B comp)) :=
  {S | ∃ w : ∀ j, (comp j).Omega, ∀ c ∈ S, c.2 ∈ (comp c.1).O (w c.1)}

/-- The (not necessarily product) randomization law for row `B`. -/
def rowDesign (B : ℕ) : FiniteDesign (∀ j : Fin B, Arr.Omega B j) :=
  Arr.rowLaw B

/-- The realized linear assignment score. -/
def score (E : Setup) (z : E.Omega) (θ : Theta E) : ℝ :=
  ∑ i, E.v z i * ((θ i : ℕ) : ℝ)

/-- The block score's design variance. -/
def sigmaSq (B : ℕ) (j : Fin B) : ℝ :=
  (Arr.rowLaw B).Var (fun w => Arr.X B j (w j))

/-- Coefficients of the design-mean target. -/
def targetCoeff (E : Setup) (i : Fin E.K) : ℝ :=
  E.design.E fun z => E.v z i

/-- The fixed-schedule causal contrast targeted by the score. -/
def targetTau (E : Setup) (θ : Theta E) : ℝ :=
  ∑ i, targetCoeff E i * ((θ i : ℕ) : ℝ)

/-- The true randomization variance as a Boolean quadratic function. -/
def trueVarianceFn (E : Setup) (θ : Theta E) : ℝ :=
  ∑ i, ∑ k, varianceMatrix E i k * ((θ i : ℕ) : ℝ) * ((θ k : ℕ) : ℝ)

/-- The unrestricted observable conservative cone denoted `C_J(f)` in the paper. -/
def unrestrictedConservativeCone (E : Setup) : Set (Theta E → ℝ) :=
  conservativeCone E ⊤

/-- Coefficient matrix of the randomization variance. -/
def varianceMatrix (E : Setup) (i k : Fin E.K) : ℝ :=
  E.design.E (fun z => E.v z i * E.v z k) - targetCoeff E i * targetCoeff E k

/-- Matrix-form packaging of `varianceMatrix`. -/
def varianceMatrixAsMatrix (E : Setup) : Matrix (Fin E.K) (Fin E.K) ℝ :=
  fun i k => varianceMatrix E i k

/-- Observation sets of the three witness assignments. -/
def witnessO (z : Fin 3) : Finset (Fin 6) :=
  match z.1 with
  | 0 => {1, 3, 5}
  | 1 => {3, 4}
  | _ => {0, 1, 2, 5}
